(()=>{const header=document.querySelector('.site-header'),menu=document.querySelector('.mobile-menu'),toggle=document.querySelector('.menu-toggle');const onScroll=()=>header.classList.toggle('scrolled',scrollY>30);onScroll();addEventListener('scroll',onScroll,{passive:true});toggle?.addEventListener('click',()=>{const open=!menu.classList.contains('open');menu.classList.toggle('open',open);document.body.classList.toggle('menu-open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Fechar menu':'Abrir menu')});menu?.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{menu.classList.remove('open');document.body.classList.remove('menu-open')}));const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;const pre=document.querySelector('.preloader');if(pre){const done=()=>pre.classList.add('done');addEventListener('load',()=>setTimeout(done,reduce?0:1350),{once:true});setTimeout(done,2600)}const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>observer.observe(el));const hero=document.querySelector('.hero'),video=hero?.querySelector('video');if(video){video.addEventListener('loadeddata',()=>hero.classList.add('has-video'));video.addEventListener('error',()=>hero.classList.remove('has-video'));if(video.readyState>=2)hero.classList.add('has-video');if(reduce){video.controls=true;video.removeAttribute('autoplay')}else{video.pause();let pending=false;addEventListener('scroll',()=>{if(pending)return;pending=true;requestAnimationFrame(()=>{const progress=Math.max(0,Math.min(1,scrollY/Math.max(hero.offsetHeight,1)));if(video.readyState>=2&&Number.isFinite(video.duration)){const target=progress*Math.max(video.duration-.05,0);if(Math.abs(video.currentTime-target)>.13)video.currentTime=target}hero.querySelector('.hero-media').style.transform=`scale(${1+progress*.12})`;pending=false})},{passive:true})}}const parallax=document.querySelector('.parallax-photo');if(parallax&&!reduce)addEventListener('scroll',()=>{const r=parallax.parentElement.getBoundingClientRect();if(r.top<innerHeight&&r.bottom>0)parallax.style.transform=`translateY(${(r.top/innerHeight)*45}px)`},{passive:true});const form=document.querySelector('#reservation-form');form?.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form),arrival=new Date(f.get('arrival')+'T12:00:00'),departure=new Date(f.get('departure')+'T12:00:00');if(departure<=arrival){form.querySelector('#departure').setCustomValidity('A saída deve ser posterior à chegada.');form.reportValidity();return}const br=d=>new Intl.DateTimeFormat('pt-BR').format(d);const msg=`Olá, Tríade. Meu nome é ${f.get('guest')}. Gostaria de consultar uma estadia de ${br(arrival)} a ${br(departure)}. Interesse: ${f.get('interest')}.${f.get('message')?` Observações: ${f.get('message')}`:''}`;window.open('https://wa.me/5527998787576?text='+encodeURIComponent(msg),'_blank','noopener')});form?.querySelector('#departure')?.addEventListener('input',e=>e.target.setCustomValidity(''))})();
